/**
 * 设置体验候选：只负责 Playground 的信息架构和组合态验证。
 *
 * 背景：正式 Settings 承载真实设置读取、自动保存、权限确认和敏感值脱敏，
 *       不能为了试验新的 IA 直接在生产面板上改默认行为。
 * 设计意图：用与生产能力对齐、但完全由 Renderer fixture 驱动的候选，先验证
 *       用户能否理解“日常设置 / 高级设置 / 低频入口”的边界。
 * 关键约束：不得调用 window.electronAPI，不展示真实 Key、MCP secret、权限规则或路径；
 *       所有开关、折叠、连接状态和输入都只存在于当前 Playground 会话。
 */
import { useEffect, useState, type ReactNode } from 'react'
import { Brain, Check, ChevronRight, CircleHelp, Cloud, Database, Download, Eye, Heart, KeyRound, Link2, LockKeyhole, Palette, Plug, Save, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Upload, UserRound, Wrench, Activity, Gauge, Plus, Server, ListChecks } from 'lucide-react'
import { DESIGN_THEME_ASSETS, FONT_SCALE_ASSETS } from '../../shared/design-asset-registry'
import { PROVIDER_PRESET_GROUPS } from '../../shared/provider-presets'

export type SettingsCandidateSection = 'appearance' | 'companion' | 'model' | 'memory' | 'data' | 'permissions' | 'extensions' | 'about'

export interface SettingsExperienceCandidateProps {
  companionDetail?: ReactNode
  memoryDetail?: ReactNode
  initialSection?: SettingsCandidateSection
  onOpenMemory?: () => void
  onOpenRoleShelf?: () => void
}

interface SettingCardProps { children: ReactNode; testId?: string }
interface SettingRowProps { children: ReactNode; description?: string; icon?: ReactNode; label: string; scope?: string; stacked?: boolean }
interface CandidateSwitchProps { checked: boolean; description: string; label: string; onChange: (checked: boolean) => void; scope?: string; testId: string }

export const SETTINGS_CANDIDATE_NAV_GROUPS: Array<{ group: string; items: Array<{ id: SettingsCandidateSection; label: string; icon: ReactNode }> }> = [
  { group: '日常', items: [
    { id: 'appearance' as const, label: '外观与界面', icon: <Palette size={15} strokeWidth={1.8} /> },
    { id: 'companion' as const, label: '伙伴与相处', icon: <Heart size={15} strokeWidth={1.8} /> },
    { id: 'model' as const, label: '模型', icon: <Cloud size={15} strokeWidth={1.8} /> },
    { id: 'memory' as const, label: '记忆与相处', icon: <Brain size={15} strokeWidth={1.8} /> },
    { id: 'data' as const, label: '数据与隐私', icon: <Database size={15} strokeWidth={1.8} /> },
  ] },
  { group: '高级', items: [
    { id: 'permissions' as const, label: '权限与自动化', icon: <ShieldCheck size={15} strokeWidth={1.8} /> },
    { id: 'extensions' as const, label: '扩展与工具', icon: <Plug size={15} strokeWidth={1.8} /> },
  ] },
]

const NAV_ITEMS: Array<{ id: SettingsCandidateSection; label: string; icon: ReactNode }> = SETTINGS_CANDIDATE_NAV_GROUPS.flatMap((group) => group.items)

function SettingCard({ children, testId }: SettingCardProps) {
  return <section className="rounded-[var(--radius-lg)] border p-4 sm:p-5" data-testid={testId} style={{ borderColor: 'var(--card-border)', background: 'var(--card-bg)' }}>{children}</section>
}

function ScopeBadge({ label }: { label: string }) {
  return <span className="shrink-0 rounded-full border px-2 py-0.5 text-[9px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-muted)' }}>{label}</span>
}

function SettingRow({ children, description, icon, label, scope, stacked = false }: SettingRowProps) {
  return <div className={`flex gap-4 ${stacked ? 'flex-col' : 'items-start justify-between'}`}>
    <div className="flex min-w-0 gap-3">
      {icon && <span className="mt-0.5 shrink-0" style={{ color: 'var(--accent-fg)' }} aria-hidden="true">{icon}</span>}
      <div className="min-w-0"><div className="flex items-center gap-2 text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}><span>{label}</span>{scope && <ScopeBadge label={scope} />}</div>{description && <p className="mt-1 max-w-xl text-[11px] leading-5" style={{ color: 'var(--text-muted)' }}>{description}</p>}</div>
    </div>
    <div className={stacked ? '' : 'shrink-0'}>{children}</div>
  </div>
}

function CandidateSwitch({ checked, description, label, onChange, scope, testId }: CandidateSwitchProps) {
  return <button type="button" role="switch" aria-checked={checked} aria-label={label} onClick={() => onChange(!checked)} className="flex w-full items-center justify-between gap-4 rounded-[var(--radius-md)] border px-3 py-3 text-left transition" style={{ borderColor: 'var(--border-subtle)', background: checked ? 'var(--accent-subtle)' : 'transparent' }} data-testid={testId}>
    <span className="min-w-0"><span className="flex items-center gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{label}{scope && <ScopeBadge label={scope} />}</span><span className="mt-0.5 block text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>{description}</span></span>
    <span className="relative h-5 w-9 shrink-0 rounded-full transition" style={{ background: checked ? 'var(--accent-emphasis)' : 'var(--bg-tertiary)' }} aria-hidden="true"><span className="absolute top-0.5 h-4 w-4 rounded-full bg-white shadow-sm transition" style={{ left: checked ? 'calc(100% - 1.125rem)' : '0.125rem' }} /></span>
  </button>
}

function CandidatePageHeader({ description, icon, title }: { description: string; icon: ReactNode; title: string }) {
  return <header className="mb-5 flex items-start justify-between gap-4"><div className="min-w-0"><div className="mb-2 flex items-center gap-2 text-[10px] font-semibold tracking-[0.16em]" style={{ color: 'var(--accent-fg)' }}><span aria-hidden="true">{icon}</span>设置样张</div><h2 className="text-xl font-semibold tracking-tight" style={{ color: 'var(--text-primary)' }}>{title}</h2><p className="mt-1 max-w-2xl text-[12px] leading-5" style={{ color: 'var(--text-muted)' }}>{description}</p></div><span className="shrink-0 rounded-full border px-2.5 py-1 text-[10px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-muted)' }}>仅供预览</span></header>
}

function AppearancePage({ activeTheme, fontScale, onFontScaleChange, onThemeChange }: { activeTheme: string; fontScale: string; onFontScaleChange: (value: string) => void; onThemeChange: (value: string) => void }) {
  return <div className="space-y-4" data-testid="settings-candidate-section-appearance"><CandidatePageHeader icon={<Palette size={14} />} title="外观与界面" description="调整应用主题和界面显示；主题选项来自基础设计资产。" /><SettingCard><SettingRow scope="本机" label="界面语言" description="当前只提供简体中文，语言切换接入前保持为说明状态。" icon={<CircleHelp size={15} />}><span className="rounded-full border px-2.5 py-1 text-[11px]" style={{ borderColor: 'var(--border-color)', color: 'var(--text-secondary)' }}>简体中文</span></SettingRow></SettingCard><SettingCard testId="settings-candidate-theme-card"><div className="mb-3 flex items-end justify-between gap-3"><div><h3 className="text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>主题</h3><p className="mt-1 text-[11px]" style={{ color: 'var(--text-muted)' }}>选择基础主题；这里的选项与应用实际使用的主题保持一致。</p></div><span className="text-[10px]" style={{ color: 'var(--text-muted)' }}>{DESIGN_THEME_ASSETS.find((theme) => theme.id === activeTheme)?.labelZh ?? activeTheme}</span></div><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{DESIGN_THEME_ASSETS.map((theme) => { const selected = activeTheme === theme.id; return <button key={theme.id} type="button" aria-pressed={selected} onClick={() => onThemeChange(theme.id)} className="rounded-[var(--radius-md)] border p-3 text-left transition" data-selected={selected ? 'true' : undefined} style={{ borderColor: selected ? 'var(--accent)' : 'var(--border-subtle)', background: selected ? 'var(--accent-subtle)' : 'transparent' }}><div className="flex items-center gap-2"><span className="h-3 w-3 rounded-full border" style={{ background: theme.representativeColor, borderColor: 'var(--border-color)' }} /><span className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{theme.labelZh}</span>{selected && <Check size={13} className="ml-auto" style={{ color: 'var(--accent-fg)' }} />}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>{theme.descriptionZh}</div></button> })}</div></SettingCard><SettingCard><SettingRow scope="本机" label="字体大小" description="只影响本机界面字号；不改变内容本身。" icon={<Eye size={15} />} stacked><div className="grid gap-2 sm:grid-cols-3">{FONT_SCALE_ASSETS.map((scale) => { const selected = fontScale === scale.id; return <button key={scale.id} type="button" aria-pressed={selected} onClick={() => onFontScaleChange(scale.id)} className="rounded-[var(--radius-md)] border px-3 py-2 text-left transition" style={{ borderColor: selected ? 'var(--accent)' : 'var(--border-subtle)', background: selected ? 'var(--accent-subtle)' : 'transparent' }}><div className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{scale.labelZh}</div><div className="mt-0.5 text-[10px]" style={{ color: 'var(--text-muted)' }}>{scale.descriptionZh}</div></button> })}</div></SettingRow></SettingCard></div>
}

function CompanionPage({ momentTips, onMomentTipsChange, onOpenRoleShelf, onProactiveGreetingChange, proactiveGreeting, expertise, onExpertiseChange }: { momentTips: boolean; onMomentTipsChange: (value: boolean) => void; onOpenRoleShelf?: () => void; onProactiveGreetingChange: (value: boolean) => void; proactiveGreeting: boolean; expertise: string; onExpertiseChange: (value: string) => void }) {
  const answerOptions = [
    ['auto', '自动', '根据问题难度调整', '简单问题直接回答，复杂问题补充步骤。'],
    ['novice', '讲清楚一些', '多补充背景和步骤', '解释为什么这样做，再带你一步步完成。'],
    ['intermediate', '重点优先', '先结论，再补关键原因', '给出做法，同时保留必要注意事项。'],
    ['expert', '直接一点', '默认进入细节', '省略基础介绍，直接给方案、参数和边界。'],
  ] as const
  return <div className="space-y-4" data-testid="settings-candidate-section-companion"><CandidatePageHeader icon={<Heart size={14} />} title="伙伴与相处" description="调整伙伴和你说话、提醒以及回应你的方式。" /><SettingCard><SettingRow scope="伙伴" label="当前伙伴" description="朋友圈、衣柜和对话都会跟随当前主角。" icon={<UserRound size={15} />}><button type="button" onClick={onOpenRoleShelf} className="inline-flex items-center gap-1 rounded-full border px-3 py-1.5 text-[11px] transition" style={{ borderColor: 'var(--border-color)', color: 'var(--text-secondary)' }} data-testid="settings-candidate-open-role-shelf">小林 · 管理角色架 <ChevronRight size={12} /></button></SettingRow></SettingCard><SettingCard><SettingRow scope="伙伴" label="回答方式" description="你希望伙伴平时怎么回答你？" icon={<Eye size={15} />} stacked><div className="grid gap-2 sm:grid-cols-2">{answerOptions.map(([value, label, description, example]) => { const selected = expertise === value; return <button key={value} type="button" aria-pressed={selected} onClick={() => onExpertiseChange(value)} className="rounded-[var(--radius-md)] border px-3 py-2.5 text-left transition" style={{ borderColor: selected ? 'var(--accent)' : 'var(--border-subtle)', background: selected ? 'var(--accent-subtle)' : 'transparent' }}><div className="flex items-center justify-between gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{label}{selected && <Check size={13} style={{ color: 'var(--accent-fg)' }} />}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-secondary)' }}>{description}</div><div className="mt-1 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>例如：{example}</div></button> })}</div></SettingRow></SettingCard><SettingCard><div className="space-y-2" data-testid="settings-candidate-companion-controls"><CandidateSwitch checked={momentTips} scope="伙伴" label="生活动态提醒" description="有新的生活动态时，在应用内轻轻提醒你。" onChange={onMomentTipsChange} testId="settings-candidate-switch-moment-tips" />{momentTips && <div className="rounded-[var(--radius-md)] border p-3" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }}><div className="mb-2 text-[11px] font-medium" style={{ color: 'var(--text-secondary)' }}>提醒节奏</div><div className="grid gap-2 sm:grid-cols-3">{[['勿扰开始', '22:00'], ['勿扰结束', '08:00'], ['每日最多', '3 条']].map(([label, value]) => <div key={label} className="rounded-[var(--radius-sm)] border px-2.5 py-2" style={{ borderColor: 'var(--border-subtle)' }}><div className="text-[10px]" style={{ color: 'var(--text-muted)' }}>{label}</div><div className="mt-1 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{value}</div></div>)}</div></div>}<CandidateSwitch checked={proactiveGreeting} scope="伙伴" label="主动问候" description="允许伙伴在合适的时机主动来打个招呼，默认保持关闭。" onChange={onProactiveGreetingChange} testId="settings-candidate-switch-proactive-greeting" /></div></SettingCard><SettingCard><SettingRow label="相处补充说明" description="告诉伙伴你希望长期保持的回应方式；这是当前样张中的临时输入。" icon={<Sparkles size={15} />} stacked><textarea aria-label="相处补充说明" defaultValue="当我把事情排得太满时，提醒我留一点空白。" rows={3} className="theme-input w-full resize-y rounded-[var(--radius-md)] border px-3 py-2 text-[12px] outline-none" /></SettingRow></SettingCard></div>
}

type ModelPurpose = 'primary' | 'auxiliary' | 'image' | 'unused'
type CapabilityState = 'supported' | 'unknown' | 'unsupported'
type ConnectionSource = 'official' | 'relay' | 'aggregator' | 'local' | 'custom'
type ModelFixture = { id: string; enabled: boolean; visibleInPicker: boolean; purpose: ModelPurpose; image: CapabilityState; tools: CapabilityState }
type ModelConnectionFixture = { id: string; name: string; source: ConnectionSource; protocol: 'OpenAI Compatible' | 'Anthropic' | 'Gemini'; providerLabel: string; baseUrl: string; credentialStatus: 'missing' | 'stored'; status: 'untested' | 'healthy' | 'failed'; models: ModelFixture[] }

const CONNECTION_SOURCE_OPTIONS: Array<{ id: ConnectionSource; label: string; description: string }> = [
  { id: 'official', label: '官方服务商', description: 'OpenAI、DeepSeek、Anthropic、Google 等' },
  { id: 'relay', label: '中转或聚合', description: 'OpenRouter、国际流动和其它网关' },
  { id: 'local', label: '本地模型', description: 'Ollama、LM Studio 等本机服务' },
  { id: 'custom', label: '自定义连接', description: '填写任意兼容协议和 Base URL' },
]

function capabilityLabel(value: CapabilityState) { return value === 'supported' ? '已确认' : value === 'unsupported' ? '不支持' : '未测试' }
function sourceLabel(value: ConnectionSource) { return CONNECTION_SOURCE_OPTIONS.find((item) => item.id === value)?.label ?? '自定义连接' }
function createConnection(provider: { providerId: string; label: string; baseUrl: string; group?: string }, index = 0): ModelConnectionFixture {
  return { id: `connection-${provider.providerId}-${index}`, name: index === 0 ? `${provider.label} 主账号` : `${provider.label} 连接`, source: provider.group === '聚合与代理' ? 'relay' : provider.group === '本地 / 自定义' ? 'local' : 'official', protocol: provider.providerId === 'anthropic' ? 'Anthropic' : provider.providerId === 'google' ? 'Gemini' : 'OpenAI Compatible', providerLabel: provider.label, baseUrl: provider.baseUrl, credentialStatus: 'stored', status: 'untested', models: index === 0 ? [{ id: 'account-model-id', enabled: true, visibleInPicker: true, purpose: 'primary', image: 'unknown', tools: 'unknown' }, { id: 'account-aux-model-id', enabled: false, visibleInPicker: false, purpose: 'auxiliary', image: 'unknown', tools: 'unknown' }, { id: 'image-model-id', enabled: true, visibleInPicker: true, purpose: 'image', image: 'unsupported', tools: 'unsupported' }] : [] }
}

function ModelPage({ modelStatus, onModelStatusChange, selectedProvider, onProviderChange }: { modelStatus: 'idle' | 'success' | 'error'; onModelStatusChange: (status: 'idle' | 'success' | 'error') => void; selectedProvider: string; onProviderChange: (provider: string) => void }) {
  const allProviders = PROVIDER_PRESET_GROUPS.flatMap((group) => group.items).filter((provider) => provider.providerId !== 'miyang')
  const firstProvider = allProviders.find((provider) => provider.providerId === selectedProvider) ?? allProviders[0]
  const [connections, setConnections] = useState<ModelConnectionFixture[]>(() => [createConnection(firstProvider)])
  const [expandedId, setExpandedId] = useState<string | null>(connections[0]?.id ?? null)
  const [showAdd, setShowAdd] = useState(false)
  const [source, setSource] = useState<ConnectionSource>('relay')
  const [providerId, setProviderId] = useState('openrouter')
  const [name, setName] = useState('')
  const [baseUrl, setBaseUrl] = useState('')
  const [apiKey, setApiKey] = useState('')
  const [modelId, setModelId] = useState('')
  const [purpose, setPurpose] = useState<ModelPurpose>('primary')
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [sessionBudget, setSessionBudget] = useState('0')
  const [dailyBudget, setDailyBudget] = useState('0')
  const [temperature, setTemperature] = useState('0.7')
  const selectedProviderConfig = allProviders.find((item) => item.providerId === providerId) ?? allProviders[0]
  const providerOptions = source === 'relay' ? allProviders.filter((item) => item.group === '聚合与代理') : source === 'local' ? allProviders.filter((item) => item.group === '本地 / 自定义') : source === 'official' ? allProviders.filter((item) => item.group === '海外直连' || item.group === '国内服务商') : []
  const openAdd = () => { setShowAdd(true); setName(''); setBaseUrl(''); setApiKey(''); setModelId(''); setPurpose('primary') }
  const chooseSource = (next: ConnectionSource) => { setSource(next); if (next === 'custom') { setName('自定义连接'); setBaseUrl(''); return }; const provider = (next === 'relay' ? allProviders.find((item) => item.providerId === 'openrouter') : providerOptions[0]); if (provider) { setProviderId(provider.providerId); setName(`${provider.label} 连接`); setBaseUrl(provider.baseUrl); onProviderChange(provider.providerId) } }
  const chooseProvider = (next: string) => { const provider = allProviders.find((item) => item.providerId === next); if (!provider) return; setProviderId(next); setName(`${provider.label} 连接`); setBaseUrl(provider.baseUrl); onProviderChange(next) }
  const finishAdd = () => { if (!name.trim() || !baseUrl.trim() || !modelId.trim()) return; const provider = selectedProviderConfig ?? { providerId: 'custom', label: '自定义连接', baseUrl }; const connection: ModelConnectionFixture = { id: `connection-${Date.now()}`, name: name.trim(), source, protocol: 'OpenAI Compatible', providerLabel: provider.label, baseUrl: baseUrl.trim(), credentialStatus: 'stored', status: 'untested', models: [{ id: modelId.trim(), enabled: true, visibleInPicker: true, purpose, image: 'unknown', tools: 'unknown' }] }; setConnections((items) => [...items, connection]); setExpandedId(connection.id); setShowAdd(false) }
  const updateModel = (connectionId: string, modelIdValue: string, patch: Partial<ModelFixture>) => setConnections((items) => items.map((connection) => connection.id !== connectionId ? connection : { ...connection, models: connection.models.map((model) => model.id === modelIdValue ? { ...model, ...patch } : model) }))
  const testConnection = (connectionId: string) => { setConnections((items) => items.map((connection) => connection.id === connectionId ? { ...connection, status: 'healthy' } : connection)); onModelStatusChange('success') }
  const setPreviewState = (state: 'empty' | 'one' | 'two') => { const first = createConnection(firstProvider); if (state === 'empty') { setConnections([]); setExpandedId(null); return }; if (state === 'one') { setConnections([first]); setExpandedId(first.id); return }; const second = createConnection(allProviders.find((item) => item.providerId === 'openrouter') ?? allProviders[1], 1); second.name = '国际流动'; second.source = 'relay'; second.models = [{ id: 'relay-model-id', enabled: true, visibleInPicker: true, purpose: 'unused', image: 'unknown', tools: 'unknown' }]; setConnections([first, second]); setExpandedId(first.id) }
  const activeModels = connections.flatMap((connection) => connection.models.filter((model) => model.enabled))
  const primary = activeModels.find((model) => model.purpose === 'primary')
  const auxiliary = activeModels.find((model) => model.purpose === 'auxiliary')
  const imageModel = activeModels.find((model) => model.purpose === 'image')
  return <div className="space-y-4" data-testid="settings-candidate-section-model">
    <CandidatePageHeader icon={<Cloud size={14} />} title="模型" description="先确认当前使用，再管理连接。官方服务商、中转站、聚合平台和自定义地址都属于连接入口；模型 ID 由你的账户决定。" />
    <SettingCard testId="settings-candidate-model-current"><div className="flex items-start justify-between gap-3"><div><h3 className="text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>当前使用</h3><p className="mt-1 text-[11px]" style={{ color: 'var(--text-muted)' }}>这里展示最终生效的模型，不只是 Provider 名称。</p></div><span className="rounded-full border px-2 py-1 text-[10px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-muted)' }}>启动时固定</span></div><div className="mt-4 grid gap-2 sm:grid-cols-3"><div className="rounded-[var(--radius-md)] border p-3" style={{ borderColor: primary ? 'var(--accent)' : 'var(--border-subtle)', background: primary ? 'var(--accent-subtle)' : 'transparent' }}><div className="text-[10px]" style={{ color: 'var(--text-muted)' }}>主对话</div><div className="mt-1 truncate font-mono text-[12px]" title={primary?.id ?? '尚未分配'} style={{ color: 'var(--text-primary)' }}>{primary?.id ?? '尚未分配'}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-secondary)' }}>{primary ? connections.find((item) => item.models.some((model) => model.id === primary.id))?.name : '添加并启用一个模型'}</div></div><div className="rounded-[var(--radius-md)] border p-3" style={{ borderColor: 'var(--border-subtle)' }}><div className="text-[10px]" style={{ color: 'var(--text-muted)' }}>辅助任务</div><div className="mt-1 truncate font-mono text-[12px]" title={auxiliary?.id ?? '沿用主对话模型'} style={{ color: 'var(--text-primary)' }}>{auxiliary?.id ?? '沿用主对话模型'}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-secondary)' }}>{auxiliary ? '标题、整理和轻量任务' : '没有单独配置'}</div></div><div className="rounded-[var(--radius-md)] border p-3" style={{ borderColor: imageModel ? 'var(--accent)' : 'var(--border-subtle)', background: imageModel ? 'var(--accent-subtle)' : 'transparent' }}><div className="text-[10px]" style={{ color: 'var(--text-muted)' }}>生图模型</div><div className="mt-1 truncate font-mono text-[12px]" title={imageModel?.id ?? '尚未配置'} style={{ color: 'var(--text-primary)' }}>{imageModel?.id ?? '尚未配置'}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-secondary)' }}>{imageModel ? '独立连接 · 用于生成图片' : '需要单独配置'}</div></div></div></SettingCard>
    <SettingCard><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h3 className="text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>已添加的模型配置</h3><p className="mt-1 text-[11px]" style={{ color: 'var(--text-muted)' }}>{connections.length ? `${connections.length} 个连接入口；每个入口可以维护多个模型。` : '还没有连接，添加后再选择模型。'}</p></div><button type="button" onClick={openAdd} className="inline-flex shrink-0 items-center gap-1 rounded-[var(--radius-md)] border px-3 py-1.5 text-[11px] font-medium" style={{ borderColor: 'var(--accent)', color: 'var(--accent-fg)' }} data-testid="settings-candidate-model-add"><Plus size={13} />添加连接</button></div>{connections.length === 0 && <div data-testid="settings-candidate-model-empty" className="mt-5 border-t pt-5 text-center" style={{ borderColor: 'var(--border-subtle)' }}><div className="text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>还没有模型连接</div><p className="mt-1 text-[11px]" style={{ color: 'var(--text-muted)' }}>添加一个连接后，才能开始对话。</p></div>}<div className="mt-4 space-y-2" data-testid="settings-candidate-model-profiles">{connections.map((connection) => { const expanded = expandedId === connection.id; return <div key={connection.id} data-testid={`settings-candidate-model-profile-${connection.providerLabel.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`} className="border-b pb-3 last:border-b-0 last:pb-0" style={{ borderColor: 'var(--border-subtle)' }}><button type="button" onClick={() => setExpandedId(expanded ? null : connection.id)} className="flex w-full items-start justify-between gap-3 text-left" aria-expanded={expanded} data-testid={`settings-candidate-connection-${connection.id}`}><span className="min-w-0"><span className="flex items-center gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{connection.name}<span className="rounded-full border px-1.5 py-0.5 text-[9px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-muted)' }}>{sourceLabel(connection.source)}</span></span><span className="mt-1 block truncate text-[10px]" title={connection.baseUrl} style={{ color: 'var(--text-muted)' }}>{connection.protocol} · {connection.models.length} 个模型 · {connection.baseUrl}</span></span><span className="flex shrink-0 items-center gap-2 text-[10px]" style={{ color: connection.status === 'healthy' ? 'var(--success)' : connection.status === 'failed' ? 'var(--danger)' : 'var(--text-muted)' }}>{connection.status === 'healthy' ? '连接正常' : connection.status === 'failed' ? '连接失败' : '未测试'}<ChevronRight size={14} className={`transition ${expanded ? 'rotate-90' : ''}`} /></span></button>{expanded && <div className="mt-3 space-y-3 border-t pt-3" style={{ borderColor: 'var(--border-subtle)' }}><div className="flex flex-wrap items-center justify-between gap-2 text-[10px]"><span style={{ color: 'var(--text-muted)' }}>连接详情 · {connection.providerLabel}</span><button type="button" onClick={() => testConnection(connection.id)} className="inline-flex items-center gap-1 rounded-[var(--radius-sm)] border px-2.5 py-1.5" style={{ borderColor: 'var(--border-subtle)', color: 'var(--accent-fg)' }}><Activity size={12} />测试连接</button></div><div className="grid gap-2 sm:grid-cols-2 text-[10px]"><div><div style={{ color: 'var(--text-muted)' }}>Base URL</div><div className="mt-1 truncate font-mono" title={connection.baseUrl} style={{ color: 'var(--text-secondary)' }}>{connection.baseUrl}</div></div><div><div style={{ color: 'var(--text-muted)' }}>密钥</div><div className="mt-1" style={{ color: connection.credentialStatus === 'stored' ? 'var(--success)' : 'var(--warning)' }}>{connection.credentialStatus === 'stored' ? '已保存（不显示原文）' : '未填写'}</div></div></div><div><div className="mb-2 text-[11px] font-medium" style={{ color: 'var(--text-primary)' }}>模型</div><div className="space-y-2">{connection.models.map((model) => <div key={model.id} className="rounded-[var(--radius-md)] border p-3" style={{ borderColor: model.purpose === 'primary' ? 'var(--accent)' : 'var(--border-subtle)', background: model.purpose === 'primary' ? 'var(--accent-subtle)' : 'transparent' }}><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="truncate font-mono text-[11px]" title={model.id} style={{ color: 'var(--text-primary)' }}>{model.id}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>{model.purpose === 'primary' ? '主对话' : model.purpose === 'auxiliary' ? '辅助任务' : '暂不使用'} · {model.enabled ? '已启用' : '已停用'}</div></div><CandidateSwitch checked={model.enabled} label={`${model.id} 启用`} description="参与模型选择" onChange={(checked) => updateModel(connection.id, model.id, { enabled: checked })} testId={`model-enabled-${model.id}`} /></div><div className="mt-3 grid gap-2 sm:grid-cols-2"><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>用途<select value={model.purpose} aria-label={`${model.id} 用途`} onChange={(event) => updateModel(connection.id, model.id, { purpose: event.target.value as ModelPurpose })} className="theme-input mt-1 w-full rounded-[var(--radius-sm)] border px-2 py-1.5 text-[10px]"><option value="primary">主对话</option><option value="auxiliary">辅助任务</option><option value="image">生图模型</option><option value="unused">暂不使用</option></select></label><div className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>能力<div className="mt-1 flex flex-wrap gap-1.5"><span className="rounded-full border px-1.5 py-0.5" style={{ borderColor: 'var(--border-subtle)' }}>文本 · 已确认</span><span className="rounded-full border px-1.5 py-0.5" style={{ borderColor: model.image === 'unsupported' ? 'var(--danger)' : 'var(--border-subtle)', color: model.image === 'unsupported' ? 'var(--danger)' : 'var(--text-muted)' }}>图片 · {capabilityLabel(model.image)}</span><span className="rounded-full border px-1.5 py-0.5" style={{ borderColor: 'var(--border-subtle)' }}>工具 · {capabilityLabel(model.tools)}</span></div></div></div><div className="mt-2 flex items-center justify-between gap-2 border-t pt-2" style={{ borderColor: 'var(--border-subtle)' }}><span className="text-[10px]" style={{ color: 'var(--text-muted)' }}>{model.visibleInPicker ? '会出现在模型选择器' : '不出现在模型选择器'}</span><button type="button" onClick={() => updateModel(connection.id, model.id, { visibleInPicker: !model.visibleInPicker })} className="text-[10px]" style={{ color: 'var(--accent-fg)' }}>{model.visibleInPicker ? '隐藏模型' : '显示模型'}</button></div></div>)}</div>{connection.models.length === 0 && <div className="border border-dashed p-3 text-[10px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-muted)' }}>还没有模型；可以手动添加 Model ID，或后续获取连接可用模型。</div>}</div></div>}</div> })}</div></SettingCard>    <SettingCard><button type="button" onClick={() => setShowAdvanced(!showAdvanced)} aria-expanded={showAdvanced} className="flex w-full items-center justify-between gap-3 text-left" data-testid="settings-candidate-model-advanced-toggle"><span className="flex items-center gap-2"><Gauge size={15} style={{ color: 'var(--accent-fg)' }} /><span><span className="block text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>高级控制</span><span className="mt-1 block text-[10px]" style={{ color: 'var(--text-muted)' }}>预算、采样和模型推理设置默认收起。</span></span></span><ChevronRight size={14} className={showAdvanced ? 'rotate-90' : ''} /></button>{showAdvanced && <div className="mt-4 space-y-4 border-t pt-4" style={{ borderColor: 'var(--border-subtle)' }}><label className="block text-[10px]" style={{ color: 'var(--text-secondary)' }}>Temperature<input aria-label="Temperature" type="number" min="0" max="2" step="0.1" value={temperature} onChange={(event) => setTemperature(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-sm)] border px-2 py-1.5 text-[11px]" /></label><div data-testid="settings-candidate-model-budget"><div className="mb-2 flex items-center gap-2 text-[11px] font-medium" style={{ color: 'var(--text-primary)' }}>运行预算<span className="rounded-full border px-1.5 py-0.5 text-[9px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-muted)' }}>全局</span></div><div className="grid gap-3 sm:grid-cols-2"><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>会话预算<input type="number" aria-label="会话预算" min="0" value={sessionBudget} onChange={(event) => setSessionBudget(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-sm)] border px-2 py-1.5 text-[11px]" /><span className="mt-1 block" style={{ color: 'var(--text-muted)' }}>{sessionBudget === '0' ? '当前：不限制' : `当前：${sessionBudget} 单位`}</span></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>每日预算<input type="number" min="0" value={dailyBudget} onChange={(event) => setDailyBudget(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-sm)] border px-2 py-1.5 text-[11px]" /></label></div></div></div>}<div className="mt-4 flex justify-end"><button type="button" onClick={() => onModelStatusChange("success")} className="inline-flex items-center gap-1 rounded-[var(--radius-sm)] border px-2.5 py-1.5 text-[10px]" style={{ borderColor: "var(--border-subtle)", color: "var(--accent-fg)" }} data-testid="settings-candidate-model-test"><Activity size={12} />测试当前连接</button></div></SettingCard>\n    <div data-testid="settings-candidate-model-status" role="status" className="sr-only">{modelStatus === "success" ? "连接配置看起来可用" : modelStatus === "error" ? "连接配置不可用" : ""}</div>\n    <SettingCard><div className="flex flex-wrap gap-1.5" role="group" aria-label="模型连接状态样张"><span className="text-[10px]" style={{ color: 'var(--text-muted)' }}>快速查看：</span>{(['empty', 'one', 'two'] as const).map((state) => <button key={state} type="button" onClick={() => setPreviewState(state)} className="settings-option px-2 py-1 text-[10px]">{state === 'empty' ? '空态' : state === 'one' ? '一个连接' : '两个连接'}</button>)}</div>{showAdd && <div className="mt-4 border-t pt-4" style={{ borderColor: 'var(--border-subtle)' }}><div className="mb-3 text-[11px] font-medium" style={{ color: 'var(--text-primary)' }}>添加连接</div><div className="grid gap-2 sm:grid-cols-2">{CONNECTION_SOURCE_OPTIONS.map((item) => <button key={item.id} type="button" onClick={() => chooseSource(item.id)} className="rounded-[var(--radius-md)] border p-3 text-left" style={{ borderColor: source === item.id ? 'var(--accent)' : 'var(--border-subtle)', background: source === item.id ? 'var(--accent-subtle)' : 'transparent' }}><div className="text-[11px] font-medium" style={{ color: 'var(--text-primary)' }}>{item.label}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>{item.description}</div></button>)}</div>{source !== 'custom' && <select value={providerId} onChange={(event) => chooseProvider(event.target.value)} className="theme-input mt-3 w-full rounded-[var(--radius-sm)] border px-2 py-2 text-[11px]" aria-label="连接入口" data-testid="settings-candidate-model-provider-select">{providerOptions.map((provider) => <option key={provider.providerId} value={provider.providerId}>{provider.label}</option>)}</select>}<div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>连接名称<input aria-label="新配置名称" value={name} onChange={(event) => setName(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-sm)] border px-2 py-2 text-[11px]" /></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>Base URL<input value={baseUrl} onChange={(event) => setBaseUrl(event.target.value)} title={baseUrl} className="theme-input mt-1 w-full rounded-[var(--radius-sm)] border px-2 py-2 font-mono text-[11px]" /></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>API Key<input type="password" value={apiKey} onChange={(event) => setApiKey(event.target.value)} placeholder="只在样张中填写，不展示原文" className="theme-input mt-1 w-full rounded-[var(--radius-sm)] border px-2 py-2 font-mono text-[11px]" /></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>模型 ID<input value={modelId} onChange={(event) => setModelId(event.target.value)} aria-label="新模型 ID" placeholder="例如：anthropic/claude-sonnet-4" title={modelId} className="theme-input mt-1 w-full rounded-[var(--radius-sm)] border px-2 py-2 font-mono text-[11px]" /></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>用途<select value={purpose} onChange={(event) => setPurpose(event.target.value as ModelPurpose)} className="theme-input mt-1 w-full rounded-[var(--radius-sm)] border px-2 py-2 text-[11px]"><option value="primary">主对话</option><option value="auxiliary">辅助任务</option><option value="unused">暂不使用</option></select></label></div><div className="mt-3 flex justify-end"><button type="button" onClick={finishAdd} data-testid="settings-candidate-model-finish-add" className="rounded-[var(--radius-md)] border px-3 py-1.5 text-[10px] font-medium" style={{ borderColor: 'var(--accent)', color: 'var(--accent-fg)' }}>添加这个连接</button></div></div>}</SettingCard>
    {modelStatus !== 'idle' && <div role="status" className="rounded-[var(--radius-md)] px-3 py-2 text-[11px]" style={{ background: modelStatus === 'success' ? 'var(--accent-subtle)' : 'color-mix(in srgb, var(--danger) 10%, transparent)', color: modelStatus === 'success' ? 'var(--accent-fg)' : 'var(--danger)' }}>{modelStatus === 'success' ? '连接测试成功（仅样张反馈）' : '连接测试失败；请检查地址和模型 ID。'}</div>}
  </div>
}
function MemoryPage({ detail }: { detail?: ReactNode }) {
  return <div className="space-y-4" data-testid="settings-candidate-section-memory"><CandidatePageHeader icon={<Brain size={14} />} title="记忆与相处" description="查看和管理会影响未来相处的长期信息。" />{detail ?? <SettingCard><div className="text-[12px]" style={{ color: 'var(--text-secondary)' }}>记忆内容由产品体验页统一管理。</div></SettingCard>}</div>
}

function DataPage({ lastAction, onAction }: { lastAction: string; onAction: (action: string) => void }) {
  return <div className="space-y-4" data-testid="settings-candidate-section-data"><CandidatePageHeader icon={<Database size={14} />} title="数据与隐私" description="管理本地数据的迁移和备份，并明确哪些内容不会跟着备份文件离开设备。" /><SettingCard><div className="grid gap-2 sm:grid-cols-2"><button type="button" onClick={() => onAction('已模拟导出')} className="flex items-center justify-between gap-3 rounded-[var(--radius-md)] border px-3 py-3 text-left transition" style={{ borderColor: 'var(--border-subtle)' }} data-testid="settings-candidate-export"><span className="flex items-center gap-2"><Upload size={15} style={{ color: 'var(--accent-fg)' }} /><span><span className="block text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>导出数据</span><span className="mt-1 block text-[10px]" style={{ color: 'var(--text-muted)' }}>生成一份本地备份</span></span></span><ChevronRight size={14} style={{ color: 'var(--text-muted)' }} /></button><button type="button" onClick={() => onAction('已模拟导入')} className="flex items-center justify-between gap-3 rounded-[var(--radius-md)] border px-3 py-3 text-left transition" style={{ borderColor: 'var(--border-subtle)' }} data-testid="settings-candidate-import"><span className="flex items-center gap-2"><Download size={15} style={{ color: 'var(--accent-fg)' }} /><span><span className="block text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>导入数据</span><span className="mt-1 block text-[10px]" style={{ color: 'var(--text-muted)' }}>从本地备份恢复</span></span></span><ChevronRight size={14} style={{ color: 'var(--text-muted)' }} /></button></div>{lastAction && <div className="mt-3 rounded-[var(--radius-md)] px-3 py-2 text-[11px]" role="status" style={{ background: 'var(--accent-subtle)', color: 'var(--accent-fg)' }}>{lastAction}（仅样张反馈）</div>}</SettingCard><SettingCard><div className="grid gap-4 sm:grid-cols-2"><div><div className="mb-2 flex items-center gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}><Save size={14} style={{ color: 'var(--accent-fg)' }} />备份包含</div><ul className="space-y-1 text-[11px] leading-5" style={{ color: 'var(--text-secondary)' }}><li>会话与消息</li><li>记忆条目</li><li>普通模型与伙伴偏好</li></ul></div><div><div className="mb-2 flex items-center gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}><LockKeyhole size={14} style={{ color: 'var(--accent-fg)' }} />备份不包含</div><ul className="space-y-1 text-[11px] leading-5" style={{ color: 'var(--text-secondary)' }}><li>API Key 和 MCP 密钥</li><li>权限规则与执行模式</li><li>本机项目路径</li></ul></div></div></SettingCard></div>
}

function PermissionsPage({ mode, onModeChange }: { mode: string; onModeChange: (value: string) => void }) {
  const [showRules, setShowRules] = useState(false)
  const [ruleTarget, setRuleTarget] = useState('命令')
  const [ruleAction, setRuleAction] = useState('拒绝')
  const [rulePattern, setRulePattern] = useState('npm publish')
  const [savedRule, setSavedRule] = useState({ target: '命令', action: '拒绝', pattern: 'npm publish' })
  return <div className="space-y-4" data-testid="settings-candidate-section-permissions"><CandidatePageHeader icon={<ShieldCheck size={14} />} title="权限与自动化" description="让你决定 Agent 什么时候先问你、什么时候按计划推进；越高风险的能力越应该明确。" /><SettingCard><div className="mb-3"><h3 className="flex items-center gap-2 text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>默认审批方式<ScopeBadge label="全局" /></h3><p className="mt-1 text-[11px]" style={{ color: 'var(--text-muted)' }}>选择一个默认方式；遇到具体操作时，你仍然可以临时调整。</p></div><div className="grid gap-2 sm:grid-cols-3">{[['auto', '自动', '只在需要时确认'], ['confirm-all', '全部确认', '每次工具调用都先问'], ['plan-first', '先计划', '先看计划再执行']].map(([value, label, description]) => { const selected = mode === value; return <button key={value} type="button" aria-pressed={selected} onClick={() => onModeChange(value)} className="rounded-[var(--radius-md)] border p-3 text-left transition" style={{ borderColor: selected ? 'var(--accent)' : 'var(--border-subtle)', background: selected ? 'var(--accent-subtle)' : 'transparent' }}><div className="flex items-center justify-between gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{label}{selected && <Check size={13} style={{ color: 'var(--accent-fg)' }} />}</div><div className="mt-1 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>{description}</div></button> })}</div></SettingCard><SettingCard><button type="button" onClick={() => setShowRules(!showRules)} aria-expanded={showRules} className="flex w-full items-center justify-between gap-3 text-left" data-testid="settings-candidate-rules-toggle"><span className="flex min-w-0 items-center gap-2"><Settings2 size={15} style={{ color: 'var(--accent-fg)' }} /><span className="min-w-0"><span className="block text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>自定义权限规则</span><span className="mt-1 block truncate text-[10px]" style={{ color: 'var(--text-muted)' }}>自己指定某类操作：允许、需要确认，或直接拒绝。</span></span></span><ChevronRight size={14} className={`transition ${showRules ? 'rotate-90' : ''}`} style={{ color: 'var(--text-muted)' }} /></button>{showRules && <div className="mt-4 space-y-4 border-t pt-4" style={{ borderColor: 'var(--border-subtle)' }}><div><div className="mb-2 text-[11px] font-medium" style={{ color: 'var(--text-secondary)' }}>已有规则样张</div><div className="flex items-center justify-between gap-3 rounded-[var(--radius-md)] border px-3 py-2.5" style={{ borderColor: 'var(--border-subtle)' }}><div><div className="text-[11px] font-medium" style={{ color: 'var(--text-primary)' }}>{savedRule.action} · {savedRule.target}</div><div className="mt-1 font-mono text-[10px]" style={{ color: 'var(--text-muted)' }}>{savedRule.pattern}</div></div><span className="rounded-full px-2 py-0.5 text-[10px]" style={{ background: savedRule.action === '拒绝' ? 'color-mix(in srgb, var(--danger) 10%, transparent)' : 'var(--accent-subtle)', color: savedRule.action === '拒绝' ? 'var(--danger)' : 'var(--accent-fg)' }}>{savedRule.action}</span></div></div><div className="rounded-[var(--radius-md)] border p-3" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }}><div className="mb-3"><div className="text-[11px] font-medium" style={{ color: 'var(--text-primary)' }}>新增一条规则</div><div className="mt-1 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>例如：拒绝发布命令；修改文件时，每次先问你。</div></div><div className="grid gap-3 sm:grid-cols-3"><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>操作类型<select aria-label="规则操作类型" value={ruleTarget} onChange={(event) => setRuleTarget(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-2.5 py-2 text-[11px] outline-none"><option>命令</option><option>修改文件</option><option>删除文件</option></select></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>处理方式<select aria-label="规则处理方式" value={ruleAction} onChange={(event) => setRuleAction(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-2.5 py-2 text-[11px] outline-none"><option>允许</option><option>需要确认</option><option>拒绝</option></select></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>匹配内容<input aria-label="规则匹配内容" value={rulePattern} onChange={(event) => setRulePattern(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-2.5 py-2 text-[11px] outline-none" placeholder="例如：npm publish" /></label></div><div className="mt-3 flex justify-end"><button type="button" onClick={() => setSavedRule({ target: ruleTarget, action: ruleAction, pattern: rulePattern || '未填写' })} className="rounded-[var(--radius-md)] border px-3 py-1.5 text-[10px] font-medium" style={{ borderColor: 'var(--accent)', color: 'var(--accent-fg)' }} data-testid="settings-candidate-save-rule">保存这条样张</button></div></div></div>}</SettingCard></div>
}

function ExtensionsPage() {
  const [skillsOpen, setSkillsOpen] = useState(false)
  const [skillsEnabled, setSkillsEnabled] = useState(true)
  const [skillsRunState, setSkillsRunState] = useState<'idle' | 'done'>('idle')
  const [mcpState, setMcpState] = useState<'empty' | 'adding' | 'connected'>('empty')
  return <div className="space-y-4" data-testid="settings-candidate-section-extensions"><CandidatePageHeader icon={<Plug size={14} />} title="扩展与工具" description="管理可以帮助伙伴完成特定任务的能力，以及需要额外连接的外部服务。" /><SettingCard><SettingRow scope="全局" label="Skills" description="按需启用能帮你完成特定任务的能力。" icon={<Wrench size={15} />}><button type="button" onClick={() => setSkillsOpen(!skillsOpen)} className="inline-flex items-center gap-1 rounded-full border px-3 py-1.5 text-[11px] transition" style={{ borderColor: 'var(--border-color)', color: 'var(--text-secondary)' }} aria-expanded={skillsOpen} data-testid="settings-candidate-skills-toggle">{skillsOpen ? '收起样张' : '查看样张'} <ChevronRight size={12} className={`transition ${skillsOpen ? 'rotate-90' : ''}`} /></button></SettingRow>{skillsOpen && <div className="mt-4 space-y-3 rounded-[var(--radius-md)] border p-3" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }}><div className="flex items-center justify-between gap-3"><div><div className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>文件整理助手</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>帮助你归纳文件、提取重点和整理结果。</div></div><CandidateSwitch checked={skillsEnabled} scope="全局" label="启用文件整理助手" description="" onChange={setSkillsEnabled} testId="settings-candidate-skills-enabled" /></div><div className="flex items-center justify-between gap-3 border-t pt-3" style={{ borderColor: 'var(--border-subtle)' }}><span className="text-[10px]" style={{ color: 'var(--text-muted)' }}>版本 <span>v1.2</span> · 已校验</span><button type="button" onClick={() => setSkillsRunState('done')} className="shrink-0 rounded-[var(--radius-md)] border px-2.5 py-1.5 text-[10px]" style={{ borderColor: 'var(--border-color)', color: 'var(--accent-fg)' }} data-testid="settings-candidate-skills-run">{skillsRunState === 'done' ? '重新试跑' : '隔离试跑'}</button></div>{skillsRunState === 'done' && <div className="rounded-[var(--radius-sm)] px-2.5 py-2 text-[10px]" role="status" style={{ background: 'var(--accent-subtle)', color: 'var(--accent-fg)' }}>已生成隔离试跑结果</div>}</div>}</SettingCard><SettingCard testId="settings-candidate-mcp-card"><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 gap-3"><span className="mt-0.5" style={{ color: 'var(--accent-fg)' }}><Link2 size={15} /></span><div><div className="flex items-center gap-2"><h3 className="text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>外部能力（MCP）</h3><ScopeBadge label="全局" /></div><p className="mt-1 text-[11px] leading-5" style={{ color: 'var(--text-muted)' }}>连接后，伙伴可以在你允许的范围内使用外部服务。</p></div></div>{mcpState === 'empty' && <button type="button" onClick={() => setMcpState('adding')} className="shrink-0 rounded-[var(--radius-md)] border px-3 py-1.5 text-[11px]" style={{ borderColor: 'var(--border-color)', color: 'var(--text-secondary)' }} data-testid="settings-candidate-mcp-add">+ 添加</button>}</div>{mcpState === 'empty' && <div className="mt-4 rounded-[var(--radius-md)] border border-dashed p-4 text-center text-[11px]" style={{ borderColor: 'var(--border-color)', color: 'var(--text-muted)' }}>还没有外部能力连接</div>}{mcpState === 'adding' && <div className="mt-4 space-y-3 rounded-[var(--radius-md)] border p-3" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }} data-testid="settings-candidate-mcp-add-form"><div className="grid gap-3 sm:grid-cols-2"><label className="text-[11px]" style={{ color: 'var(--text-secondary)' }}>显示名称<input aria-label="MCP 显示名称" placeholder="例如：文件工具" className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-3 py-2 text-[12px] outline-none" /></label><label className="text-[11px]" style={{ color: 'var(--text-secondary)' }}>连接方式<select aria-label="MCP 连接方式" className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-3 py-2 text-[12px] outline-none"><option>本地命令</option><option>远程地址</option></select></label></div><div className="flex items-center justify-between gap-3"><span className="text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>连接前会让你确认它需要访问的范围。</span><div className="flex gap-2"><button type="button" onClick={() => setMcpState('empty')} className="rounded-[var(--radius-md)] px-3 py-1.5 text-[11px]" style={{ color: 'var(--text-muted)' }}>取消</button><button type="button" onClick={() => setMcpState('connected')} className="rounded-[var(--radius-md)] border px-3 py-1.5 text-[11px] font-medium" style={{ borderColor: 'var(--accent)', color: 'var(--accent-fg)' }} data-testid="settings-candidate-mcp-connect">完成样张连接</button></div></div></div>}{mcpState === 'connected' && <div className="mt-4 flex items-center justify-between gap-3 rounded-[var(--radius-md)] border px-3 py-3" style={{ borderColor: 'color-mix(in srgb, var(--success) 40%, var(--border-color))', background: 'color-mix(in srgb, var(--success) 8%, transparent)' }}><div className="flex items-center gap-2"><span className="h-2 w-2 rounded-full" style={{ background: 'var(--success)' }} /><div><div className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>文件工具 · 已连接</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>样张状态 · 3 个能力</div></div></div><button type="button" onClick={() => setMcpState('empty')} className="rounded-[var(--radius-md)] px-2 py-1 text-[10px]" style={{ color: 'var(--danger)' }}>移除样张</button></div>}</SettingCard></div>
}

function AboutPage() {
  return <div className="space-y-4" data-testid="settings-candidate-section-about"><CandidatePageHeader icon={<CircleHelp size={14} />} title="关于 My Agent" description="查看版本、运行环境和本机数据位置。" /><SettingCard><div className="flex items-start gap-3"><Sparkles size={18} style={{ color: 'var(--companion-accent-warm)' }} /><div><div className="text-[15px] font-semibold" style={{ color: 'var(--text-primary)' }}>My Agent</div><p className="mt-1 text-[12px]" style={{ color: 'var(--text-muted)' }}>品牌标语待定</p></div></div><div className="mt-5 grid gap-3 text-[11px] sm:grid-cols-3" style={{ color: 'var(--text-secondary)' }}><div><div style={{ color: 'var(--text-muted)' }}>版本</div><div className="mt-1">0.1.0 · 开发中</div></div><div><div style={{ color: 'var(--text-muted)' }}>运行环境</div><div className="mt-1">Electron</div></div><div><div style={{ color: 'var(--text-muted)' }}>数据位置</div><div className="mt-1">本机存储</div></div></div></SettingCard></div>
}

export function SettingsExperienceCandidate({ companionDetail, memoryDetail, initialSection, onOpenMemory, onOpenRoleShelf }: SettingsExperienceCandidateProps) {
  const [activeSection, setActiveSection] = useState<SettingsCandidateSection>(initialSection ?? 'appearance')
  const [activeTheme, setActiveTheme] = useState('mist')
  const [fontScale, setFontScale] = useState('md')
  const [momentTips, setMomentTips] = useState(true)
  const [proactiveGreeting, setProactiveGreeting] = useState(false)
  const [modelStatus, setModelStatus] = useState<'idle' | 'success' | 'error'>('idle')
  const [selectedProvider, setSelectedProvider] = useState('openai')
  const [expertise, setExpertise] = useState('auto')
  const [dataAction, setDataAction] = useState('')
  const [permissionMode, setPermissionMode] = useState('auto')

  useEffect(() => {
    // 场景从“记忆管理”返回普通设置时回到默认入口，避免保留上一场景的局部上下文。
    setActiveSection(initialSection ?? 'appearance')
  }, [initialSection])

  const activeSectionLabel = [...NAV_ITEMS, { id: 'about' as const, label: '关于 My Agent', icon: <CircleHelp size={15} /> }].find((item) => item.id === activeSection)?.label ?? '设置'

  return <div aria-label="设置候选版" className="flex min-h-[620px] w-full min-w-0 overflow-hidden rounded-[var(--radius-lg)] border" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-primary)' }} data-testid="settings-candidate"><aside className="hidden w-[198px] shrink-0 flex-col border-r px-3 py-4 md:flex" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }} data-testid="settings-nav"><div className="mb-5 px-2"><div className="text-[11px] font-semibold tracking-[0.18em]" style={{ color: 'var(--text-primary)' }}>设置</div><p className="mt-1 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>把真正需要决定的事放在眼前。</p></div><nav className="flex-1 space-y-5" aria-label="设置候选导航">{SETTINGS_CANDIDATE_NAV_GROUPS.map((group) => <div key={group.group}><div className="mb-1 px-2 text-[10px] font-semibold" style={{ color: 'var(--text-muted)' }}>{group.group}</div><div className="space-y-0.5">{group.items.map((item) => { const active = item.id === activeSection; return <button key={item.id} type="button" aria-current={active ? 'page' : undefined} aria-controls={`settings-candidate-panel-${item.id}`} title={item.label} onClick={() => setActiveSection(item.id)} className="settings-nav-item flex w-full items-center gap-2 px-2.5 py-2 text-left text-[12px] transition" style={{ color: active ? 'var(--text-primary)' : 'var(--text-secondary)', background: active ? 'var(--hover-overlay)' : undefined }} data-testid={`settings-candidate-nav-${item.id}`}><span style={{ color: active ? 'var(--accent-fg)' : 'var(--text-muted)' }}>{item.icon}</span><span className="min-w-0 truncate">{item.label}</span>{active && <ChevronRight size={12} className="ml-auto shrink-0" style={{ color: 'var(--text-muted)' }} />}</button> })}</div></div>)}</nav><div className="mt-5 border-t pt-3" style={{ borderColor: 'var(--border-subtle)' }}><button type="button" onClick={() => setActiveSection('about')} aria-current={activeSection === 'about' ? 'page' : undefined} aria-controls="settings-candidate-panel-about" title="关于 My Agent" className="settings-nav-item flex w-full items-center gap-2 px-2.5 py-2 text-left text-[12px]" style={{ color: activeSection === 'about' ? 'var(--text-primary)' : 'var(--text-secondary)', background: activeSection === 'about' ? 'var(--hover-overlay)' : undefined }} data-testid="settings-candidate-nav-about"><CircleHelp size={15} style={{ color: activeSection === 'about' ? 'var(--accent-fg)' : 'var(--text-muted)' }} />关于 My Agent</button><p className="mt-3 px-2 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>Debug / Playground 使用应用全局入口，不在这里复制第二套导航。</p></div></aside><div className="flex min-w-0 flex-1 flex-col"><div className="min-w-0 overflow-hidden border-b px-3 py-2 md:hidden" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }}><div className="flex min-w-0 w-full gap-1 overflow-x-auto" role="tablist" aria-label="设置候选导航" data-testid="settings-candidate-mobile-nav">{NAV_ITEMS.map((item) => { const active = item.id === activeSection; return <button key={item.id} type="button" role="tab" aria-selected={active} aria-controls={`settings-candidate-panel-${item.id}`} title={item.label} onClick={() => setActiveSection(item.id)} className="settings-option shrink-0 px-2.5 py-1.5 text-[10px]" data-selected={active ? 'true' : undefined}>{item.label}</button> })}<button type="button" role="tab" aria-selected={activeSection === 'about'} aria-controls="settings-candidate-panel-about" title="关于 My Agent" onClick={() => setActiveSection('about')} className="settings-option shrink-0 px-2.5 py-1.5 text-[10px]" data-selected={activeSection === 'about' ? 'true' : undefined}>关于</button></div></div><main className="scrollbar-thin min-h-0 flex-1 overflow-y-auto px-4 py-5 sm:px-6" data-testid="settings-main"><div key={activeSection} id={`settings-candidate-panel-${activeSection}`} role="tabpanel" aria-label={activeSectionLabel} className="view-transition mx-auto w-full max-w-3xl" data-testid="settings-candidate-content">{activeSection === 'appearance' && <AppearancePage activeTheme={activeTheme} fontScale={fontScale} onFontScaleChange={setFontScale} onThemeChange={setActiveTheme} />}{activeSection === 'memory' && <MemoryPage detail={memoryDetail} />}{activeSection === 'companion' && (companionDetail ?? <CompanionPage expertise={expertise} momentTips={momentTips} onExpertiseChange={setExpertise} onOpenRoleShelf={onOpenRoleShelf} onMomentTipsChange={setMomentTips} onProactiveGreetingChange={setProactiveGreeting} proactiveGreeting={proactiveGreeting} />)}{activeSection === 'model' && <ModelPage modelStatus={modelStatus} onModelStatusChange={setModelStatus} selectedProvider={selectedProvider} onProviderChange={setSelectedProvider} />}{activeSection === 'data' && <DataPage lastAction={dataAction} onAction={setDataAction} />}{activeSection === 'permissions' && <PermissionsPage mode={permissionMode} onModeChange={setPermissionMode} />}{activeSection === 'extensions' && <ExtensionsPage />}{activeSection === 'about' && <AboutPage />}</div></main></div></div>
}
